-- Features (drive the mega menu and /Features pages)
INSERT INTO cmr_admin.site_feature (slug,title,icon,live_status,lead,points,steps,has_app,app_label,group_title,menu_column,group_order,sort_order,is_home_highlight) VALUES
  ('salesman-app','Salesman app','📱','live','A fast order-taking app for your field team – live stock, rates and each retailer''s balance, even on weak networks.',ARRAY['Search products by name or SKU and add in two taps','See stock and last rate before you quote','Retailer outstanding and credit limit shown at checkout','Wishlist of fast-moving items for quick reorders']::text[],ARRAY['Pick the retailer','Add items to the cart','Place the order – it reaches the office instantly']::text[],true,'Open catalogue','Taking the order',1,1,1,true),
  ('sales-orders','Sales orders','📝','live','Every order from every salesman in one list – filter, sort and turn it into an invoice without re-typing.',ARRAY['Status tracking: awaiting approval, pending, delivered, cancelled','Search by invoice number or customer','Cancelling an order puts stock back automatically','Print or share invoices in one tap']::text[],ARRAY['Order is placed','Office reviews and delivers','Invoice syncs to Tally']::text[],true,'Open orders','Taking the order',1,1,2,false),
  ('voucher-approval','Voucher approval','✅','live','Orders from retailers'' self-order links wait for your approval before stock moves or vouchers post.',ARRAY['Approve or reject with one click','Stock is checked at approval time','Nothing reaches Tally until approved','Notification when a new order is waiting']::text[],ARRAY['Retailer submits via link','You review the order','Approve – stock and invoice update']::text[],true,'Review orders','Taking the order',1,1,3,false),
  ('customer-order-link','Customer order link','🔗','live','Give every retailer a personal link. They place orders themselves from their phone – no app install.',ARRAY['One shareable link per retailer','Share on WhatsApp straight from the customers page','Orders land in your approval queue','Retailers see live rates and availability']::text[],ARRAY['Copy the retailer''s link','Share on WhatsApp','Approve incoming orders']::text[],true,'Get order links','Taking the order',1,1,4,false),
  ('e-invoice','E-invoice from phone','🧾','sim','Generate IRN and acknowledgement details for an invoice from the invoice screen.',ARRAY['IRN and Ack number stored on the invoice','Printed on the invoice automatically','In this demo the IRN is generated locally – the real GST portal is not contacted','Production use needs your GSP credentials']::text[],ARRAY['Open an invoice','Tap Generate e-invoice','IRN appears on the invoice']::text[],true,'Open an invoice','Making the bill',1,2,1,false),
  ('e-way-bill','E-way bill from phone','🚚','sim','Capture vehicle and distance, produce an e-way bill number and keep it with the invoice.',ARRAY['Vehicle number and distance captured at dispatch','E-way bill number stored on the invoice','Demo generates a local number – not filed with the portal','Reprint any time from the invoice page']::text[],ARRAY['Open the invoice','Enter vehicle and distance','Bill number is saved']::text[],true,'Open an invoice','Making the bill',1,2,2,false),
  ('credit-debit-notes','Credit and debit notes','↩️','live','Record sales returns, rate differences and extra charges. Balances and ageing update instantly.',ARRAY['Credit notes reduce a retailer''s outstanding','Debit notes add to it','Entries appear in the party ledger','Exported to Tally as journal-style vouchers']::text[],ARRAY['Open Receivables','Choose Note on a retailer','Balance updates']::text[],true,'Open receivables','Making the bill',1,2,3,false),
  ('import-purchase-pdf','Import purchase from PDF','📄','mobile','Drop in a supplier''s PDF invoice and have the purchase voucher drafted for you.',ARRAY['Reads supplier, items, rates and GST','Flags items that do not match your masters','You review before it posts to Tally','Delivered in the production desktop connector']::text[],ARRAY['Upload the PDF','Match items','Post purchase voucher']::text[],false,'Open in app','Making the bill',1,2,4,false),
  ('order-from-photo','Order from a photo','📷','mobile','Photograph a handwritten order slip and turn it into a draft order.',ARRAY['Recognises item names and quantities','Maps them to your catalogue','You confirm before placing','Delivered in the production mobile app']::text[],ARRAY['Click a photo','Review the draft','Place order']::text[],false,'Open in app','Making the bill',1,2,5,false),
  ('bank-statement-import','Bank statement import','🏦','live','Upload a bank statement CSV and match credits to retailers'' open invoices.',ARRAY['Matches by retailer name in the narration or exact amount','You choose the retailer when unsure','Posts receipts in bulk','Ageing refreshes straight away']::text[],ARRAY['Upload CSV','Review suggested matches','Post receipts']::text[],true,'Open bank import','Making the bill',1,2,6,false),
  ('godown-stock','Godown wise stock','🏭','mobile','Track stock per godown, allocate at billing time and print loading sheets.',ARRAY['Stock by location','Allocation at billing','Loading list by route','This demo tracks a single stock figure per product']::text[],ARRAY['Set up godowns','Allocate on billing','Print loading list']::text[],true,'View stock','Loading and stock',2,1,1,false),
  ('delivery-challans','Delivery challans','📦','live','Print a price-free delivery challan for the driver straight from any invoice.',ARRAY['Quantity-only layout for the driver','Free goods listed clearly','Signature box for the receiver','Same data as the invoice – nothing to re-enter']::text[],ARRAY['Open an invoice','Tap Delivery challan','Print']::text[],true,'Open an invoice','Loading and stock',2,1,2,false),
  ('invoice-template','Invoice template','🎨','live','Choose the look of your invoice and add your footer note and UPI ID.',ARRAY['Classic, compact or modern layouts','Custom footer text','UPI ID printed for easy payment','Applies to every invoice instantly']::text[],ARRAY['Open Settings','Pick a template','Print any invoice']::text[],true,'Open settings','Sending it to the customer',2,2,1,false),
  ('ledger-on-whatsapp','Ledger on WhatsApp','📒','live','Send a retailer their statement – invoices, receipts and balance – as a WhatsApp message.',ARRAY['Statement text built from the ledger','Editable template','Opens WhatsApp with the message ready','Every send is logged']::text[],ARRAY['Pick the retailer','Choose the Ledger template','Send on WhatsApp']::text[],true,'Open WhatsApp centre','Sending it to the customer',2,2,2,true),
  ('payment-reminders','Payment reminders','⏰','live','Send a friendly reminder with the amount, oldest invoice and a UPI payment link.',ARRAY['One-tap reminder from the receivables list','Template with your wording','UPI link included','Reminder history in the message log']::text[],ARRAY['Open Receivables','Tap Remind','Send on WhatsApp']::text[],true,'Open receivables','Reminding and collecting',2,3,1,false),
  ('automatic-reminders','Automatic reminders','🤖','sim','Set rules once – minimum amount, days overdue, repeat gap – and let SyncTally queue reminders every day.',ARRAY['Rules per account','Daily run builds the queue','Demo queues messages for you to send; fully automatic sending needs the WhatsApp Business API on a server','Run now to preview']::text[],ARRAY['Enable rules','Queue is built daily','Review and send']::text[],true,'Open automation','Reminding and collecting',2,3,2,false),
  ('outstanding-receivables','Outstanding receivables','💼','live','Know who owes what, instantly – by retailer, with credit-limit warnings.',ARRAY['Total and overdue amounts','Retailers above credit limit flagged','Open the ledger in one tap','Same figures as Tally']::text[],ARRAY['Open Receivables','Sort by amount','Act on the top debtors']::text[],true,'Open receivables','Recovering what is overdue',3,1,1,true),
  ('debtor-ageing','Debtor ageing','📊','live','See each retailer''s balance split by 0–30, 31–60, 61–90 and 90+ days.',ARRAY['FIFO allocation of receipts to oldest invoices','Bucket totals at the top','Focus on the oldest money first','Export to CSV from Reports']::text[],ARRAY['Open Receivables','Read the buckets','Chase the oldest']::text[],true,'Open ageing','Recovering what is overdue',3,1,2,false),
  ('payment-collection','Payment collection','💰','live','Record cash, UPI, cheque and bank receipts in the field; they settle the oldest invoices first.',ARRAY['Cash, UPI, cheque, bank','Partial payments supported','Receipt exported to Tally','Collection total on the dashboard']::text[],ARRAY['Tap Receipt','Enter amount and mode','Ageing updates']::text[],true,'Record a receipt','Recovering what is overdue',3,1,3,false),
  ('ai-collection-calls','AI collection calls','📞','sim','A prioritised call queue with a suggested script, and a place to log promises-to-pay.',ARRAY['Queue sorted by amount and age','Script suggestion for each call','Outcome and promise date logged','Demo does not place calls – telephony is a paid add-on']::text[],ARRAY['Open the call queue','Call and log outcome','Follow up on promises']::text[],true,'Open call queue','Recovering what is overdue',3,1,4,false),
  ('tally-on-mobile','Tally on mobile','🔄','sim','The Tally Connector links SyncTally to your Tally so masters come in and vouchers go back.',ARRAY['Pair with a 6-digit code','Push invoices and receipts as Tally XML','Import items and ledgers from CSV','Demo simulates the live link; XML you download imports into real Tally']::text[],ARRAY['Download the connector config','Pair and test','Sync']::text[],true,'Open connector','Back in Tally',3,2,1,true),
  ('without-remote-access','Without remote access','🔒','sim','No remote desktop needed – the connector talks to Tally on your own PC and only sends what the app needs.',ARRAY['Tally data stays on your PC','Outbound connection only','Read-only for salesmen','Audit trail of each sync']::text[],ARRAY['Install connector on the Tally PC','Pair once','Sync automatically']::text[],true,'Open connector','Back in Tally',3,2,2,true),
  ('reports-on-mobile','Reports on mobile','📈','live','Sales by customer, product, category and payment mode – with date filters and CSV export.',ARRAY['7 / 30 / 90-day and all-time views','Top customers and products','CSV export','Always current – no waiting for month end']::text[],ARRAY['Open Reports','Pick a view','Export if needed']::text[],true,'Open reports','Back in Tally',3,2,3,false),
  ('multi-company','Multi-company','🏢','live','Run more than one company and switch between them. The active company prints on invoices.',ARRAY['Add companies in Settings','Switch active company any time','Company name saved on each invoice','Separate Tally company per entity in the connector']::text[],ARRAY['Open Settings','Add a company','Switch when billing']::text[],true,'Open settings','Back in Tally',3,2,4,false),
  ('schemes','Schemes','🎁','live','Set “buy 10 get 1 free” or percentage discounts. They apply automatically when an order qualifies.',ARRAY['Free goods or discount % per product','Minimum quantity rules','Applied in the cart and on the invoice','Free goods reduce stock']::text[],ARRAY['Create a scheme','Salesman adds quantity','Scheme applies itself']::text[],true,'Open schemes','Schemes and discounts',4,1,1,true),
  ('fmcg-module','FMCG module','🛒','live','Built for fast-moving goods: case sizes, schemes, GST slabs and route-wise selling.',ARRAY['Pack sizes on every item','Scheme engine','Route-wise retailers by city','Fast reorder through wishlist']::text[],ARRAY['Load your items','Add schemes','Take orders']::text[],true,'Open catalogue','Schemes and discounts',4,1,2,false),
  ('autoparts-billing','AutoParts billing','🔩','mobile','Part numbers, vehicle fitment and MRP-based billing for auto-spares counters.',ARRAY['Part-number search','Fitment lookup','MRP and discount billing','Available as a vertical pack']::text[],ARRAY['Import part catalogue','Search by vehicle','Bill']::text[],false,'Open in app','Schemes and discounts',4,1,3,false),
  ('ladder-discount','Ladder discount','🪜','live','Reward bigger orders: define several slabs for one product and the best qualifying slab applies.',ARRAY['Multiple slabs per product','Highest qualifying slab wins','Visible in the cart before checkout','Printed on the invoice']::text[],ARRAY['Add slabs in Schemes','Qty increases','Higher slab applies']::text[],true,'Open schemes','Schemes and discounts',4,1,4,false),
  ('fmcg-distributors','FMCG distributors','🧴','live','Orders, schemes, outstanding and collections for FMCG stockists and super-stockists.',ARRAY['Schemes and ladder slabs','Route-wise ageing','Retailer self-order links','Daily sales and collection reports']::text[],ARRAY['Import retailers','Add schemes','Take orders']::text[],true,'Open dashboard','Built for your trade',4,2,1,false),
  ('pharma-distributors','Pharma distributors','💊','mobile','Batch, expiry and strip-level billing for pharma wholesalers.',ARRAY['Batch and expiry on each line','Near-expiry alerts','Strip / box conversion','Delivered as the pharma pack']::text[],ARRAY['Enable pharma pack','Receive stock by batch','Bill by batch']::text[],false,'Open in app','Built for your trade',4,2,2,false),
  ('agri-input-distributors','Agri-input distributors','🌾','mobile','Seasonal credit, farmer ledgers and licence-wise billing for agri-input dealers.',ARRAY['Seasonal credit cycles','Farmer ledgers','Licence number on invoices','Delivered as the agri pack']::text[],ARRAY['Enable agri pack','Set season terms','Bill and collect']::text[],false,'Open in app','Built for your trade',4,2,3,false);

-- Home page journey
INSERT INTO cmr_admin.site_journey_step (icon,title,description,sort_order) VALUES
  ('📝','Order taking','Salesmen take orders at the shop counter from a phone – with live stock, rates, schemes and each retailer''s outstanding balance in view.',1),
  ('🧾','Billing','Convert orders into GST invoices in one tap. Split by godown or salesman, with e-invoice and e-way bill details ready.',2),
  ('📦','Loading & stock','Godown-wise stock, loading lists and delivery challans so the right goods leave on the right truck.',3),
  ('🚚','Delivery','Invoices reach retailers on WhatsApp the moment goods are dispatched, with a secure payment link.',4),
  ('⏰','Reminders','Automatic WhatsApp reminders for overdue invoices, scheduled by customer, route or ageing bucket.',5),
  ('💰','Collections','Track promises-to-pay, record receipts in the field and see which salesman is recovering how much.',6),
  ('🔄','Tally sync','Orders, invoices and receipts flow into Tally automatically – no re-typing, no month-end reconciliation scramble.',7);

-- FAQ
INSERT INTO cmr_admin.site_faq (question,answer,sort_order) VALUES
  ('Does SyncTally work with my version of Tally?','Yes – it works with Tally Prime and Tally ERP 9 through a small connector installed on the PC where Tally runs.',1),
  ('Where is my data stored?','Your Tally data stays on your own computer. Only the order and outstanding information needed by the app is synced, and salesmen have restricted, role-based access.',2),
  ('Is there a free trial?','Every account starts with a 15-day trial with all features switched on. No card required.',3),
  ('Can salesmen work offline?','They can capture orders offline; the app syncs automatically when the network returns.',4),
  ('What does it cost?','Plans start at ₹1,999 per year. See the pricing page for details.',5);

