-- Blog posts
INSERT INTO cmr_admin.site_blog_post (slug,title,tag,icon,published_on,read_minutes,excerpt,body,author,author_role,is_featured,view_count) VALUES
  ('cut-evening-data-entry','How distributors are cutting evening data entry to zero','Distribution','🌙','2026-09-18',5,'The nightly ritual of re-typing orders into Tally is optional. Here is what the switch looks like, step by step, and what it saves.',ARRAY['Walk into almost any distributor''s office at seven in the evening and you will see the same scene: salesmen''s order slips on one side, a Tally screen on the other, and an operator typing between them. It is slow, it is error-prone, and it is entirely avoidable.','## Where the hours actually go','A typical operator spends two to four hours a day re-keying orders. Most of that time is not typing at all; it is deciphering handwriting, phoning a salesman to confirm an item, and fixing the voucher after the retailer disputes the rate.','- Handwritten slips lose quantities and units in transit.','- Rates differ by retailer, but the slip rarely says which rate was used.','- Stock is checked after the order, not while it is being taken.','> The cheapest data entry is the entry nobody has to do. Capture once, at the counter, and let the voucher write itself.','## What changes with SyncTally','The salesman takes the order on a phone, against live stock and the retailer''s own rate list. When he submits, the order lands in the office queue. One review, one click, and it becomes a Sales Order in Tally through the connector.','## What to expect in the first month','Expect the first week to feel slower because everyone is learning. By week three most teams report that evening entry has dropped to a quick review, and by week four the operator has moved on to collections follow-up, which is where the real money is.','## A simple rollout plan','- Pick two salesmen who are comfortable with phones.','- Run their orders through SyncTally in parallel with paper for one week.','- Compare totals daily; fix rate lists where they differ.','- Move the rest of the team once the numbers match.'],'Rahul Menon','Product Manager',true,93),
  ('ageing-report-habits','Five habits for a healthier ageing report','Collections','📊','2026-09-02',6,'Old receivables rarely recover. These routines keep money from ever going stale.',ARRAY['An ageing report is a mirror. If the 90-plus column keeps growing, the problem is not the customers; it is the routine around them.','## 1. Read it every Monday','Make the ageing report the first thing the owner and the accounts head look at each week. Ten minutes, same time, same format. A report nobody reads is only a pile of numbers.','## 2. Chase at day 20, not day 60','By the time an invoice is two months old, the retailer has paid three newer suppliers. A polite reminder on day 20 of a 30-day credit period gets you into the payment run.','## 3. Assign every large balance to a person','- Balances above a limit you choose get a named owner.','- The owner records the promised date and amount.','- A missed promise is reviewed the next Monday.','## 4. Stop supply at a clear limit','Credit limits that are only advisory are not limits. Decide the number, communicate it, and let the order screen warn the salesman before he books more.','> A retailer who knows the rule rarely tests it.','## 5. Close the loop with the ledger','Unallocated receipts quietly inflate the old columns. Allocate every receipt against its bill the same day, and the report becomes honest again.'],'Anil Kapoor','Tally Consultant',false,130),
  ('schemes-that-work','Schemes that work: free goods versus ladder discounts','Schemes','🎁','2026-08-20',5,'Two common promotion styles, and how to choose between them for your retailers.',ARRAY['Promotions fail more often because of confusion than because of cost. If the retailer cannot work out the benefit in five seconds, the scheme does not exist for him.','## Free goods','Buy ten cartons, get one free. It is easy to say, easy to remember, and it protects your invoice rate. It works best on fast-moving items where the free pack is a visible gift.','## Ladder discounts','The more you buy, the higher the percentage. Ladders reward larger baskets and are better when you want to lift average order value rather than move one specific item.','## Choosing between them','- Use free goods to clear a slow line or launch a new pack.','- Use a ladder to grow the basket across the whole range.','- Avoid stacking both on the same item; the arithmetic becomes unreadable.','## Making either one work in practice','Whichever you choose, the scheme must be applied automatically when the order is taken. If the salesman has to remember it, half of the benefit will be lost and the other half will be disputed at billing.','> Write the scheme once, apply it everywhere, and show the retailer the saving on the order itself.'],'Priya Nair','Customer Success',false,167),
  ('tally-connector-explained','The Tally connector, explained in plain language','Integration','🔌','2026-08-05',4,'What runs where, what leaves your PC, and what never does.',ARRAY['The connector is a small Windows program that sits next to Tally and talks to it. It is the only bridge between the cloud and your books.','## What it does','It reads masters such as ledgers, items and rates from Tally, and it writes vouchers back. That is all. It does not copy your company data folder and it does not need Tally to be exposed to the internet.','## What leaves your PC','- Ledger and item names with rates and balances needed for ordering.','- Outstanding bills used for collections.','Nothing else is sent. Voucher narrations, bank details and payroll data stay where they are.','## Keeping it healthy','- Leave the connector running on the PC where Tally is open.','- Check the status badge in the app; green means synced.','- If it turns amber, restart Tally and the connector, in that order.','## When Tally is closed','Orders still arrive and wait in the queue. When Tally opens again, the connector posts them in sequence. Nothing is lost and nothing is duplicated.'],'Rahul Menon','Product Manager',false,204),
  ('whatsapp-reminders-etiquette','WhatsApp reminder etiquette that actually gets you paid','Receivables','💬','2026-07-22',4,'Tone, timing and a payment link: the three parts of a reminder retailers respond to.',ARRAY['A reminder is a request, not an accusation. The retailers who pay fastest are usually the ones who were asked politely and made it easy.','## Tone','Greet by name, state the amount and the invoice date, and thank them for their business. Skip capital letters and exclamation marks.','## Timing','Send during business hours, never late at night, and not more than once in three days unless a promise was broken. Mid-morning, after the shop has opened, gets the best response.','## Make paying effortless','- Include the exact amount.','- Add your UPI details or a payment link.','- Ask for a date, not a yes or no.','> "Could you confirm when we can expect the payment of ₹18,450 for invoice 2231?" is far more effective than "Please pay soon."','## Keep a record','Log every reminder and every promised date. When a retailer says he already paid, you will be able to answer calmly with facts.'],'Priya Nair','Customer Success',false,241),
  ('field-sales-first-week','A salesman''s first week on a phone app: what to expect','Field Sales','📱','2026-09-24',5,'New to taking orders on a phone? Here is a day-by-day plan that has worked for dozens of teams.',ARRAY['Teams that struggle with a mobile order app almost always skipped the first week. A little structure there saves months later.','## Day 1: Install and explore','Sign in, look at today''s route, and open three retailers. Do not take real orders yet. The aim is to get comfortable with where things are.','## Day 2: Shadow orders','Take your normal paper orders, then enter the same ones in the app after the visit. It will feel slow; that is fine.','## Day 3 and 4: Live orders, safety net on','Enter orders in front of the retailer, still keeping the paper slip. Compare totals in the evening.','## Day 5: Paper goes in the drawer','By now most salesmen are faster on the phone than on paper. Keep the slips for one more week, just in case.','## Tips from the field','- Download the day''s retailer list before leaving the office.','- Use the search box rather than scrolling long item lists.','- Take the photo of the shop shelf when a retailer raises a stock complaint.'],'Priya Nair','Customer Success',false,278),
  ('daybook-vs-orders','Why your day book and your order book disagree','Reports','📒','2026-06-30',5,'Two reports, two totals. Understanding the gap makes both of them more useful.',ARRAY['It is common to find that the total in the order book on Monday does not match the sales in the day book on Tuesday. That is not an error; it is a timing difference you can measure.','## Orders are intentions, sales are facts','An order is a promise. Billing happens when stock leaves the godown. In between sits a pipeline of pending and partially supplied orders.','## The three usual gaps','- Orders cancelled by the retailer after booking.','- Items supplied short because stock ran out.','- Orders billed on the following day.','## How to reconcile in five minutes','Filter the order book by status, add the pending value to the billed value and the cancelled value, and compare with the total booked. When the three add up, the books agree.','> A pending-orders list that is reviewed daily is the best early-warning system for lost sales.'],'Anil Kapoor','Tally Consultant',false,315),
  ('credit-limit-control','Setting credit limits retailers will accept','Collections','🛡️','2026-06-12',4,'A limit only works if it is fair, visible and applied the same way to everyone.',ARRAY['Credit limits are about protecting the business and the relationship at the same time.','## Start with the data','Look at each retailer''s average monthly purchase and how long he usually takes to pay. A sensible limit is roughly one and a half times his normal outstanding.','## Communicate before you enforce','Tell the retailer his limit and the reason. A surprise block at order time is the fastest way to lose a good customer.','## Use three levels','- Green: within limit, order proceeds.','- Amber: close to limit, salesman is warned and the owner is told.','- Red: over limit, order waits for approval.','## Review quarterly','Limits should move with the business. A retailer who has paid on time for six months deserves a raise, and a late payer deserves a conversation.'],'Anil Kapoor','Tally Consultant',false,352),
  ('gst-invoice-checklist','A GST invoice checklist for distributors','Compliance','🧾','2026-05-27',5,'Small mistakes on invoices cause big headaches at return time. Check these before you print.',ARRAY['This is a practical checklist, not legal advice. Always confirm requirements with your chartered accountant.','## Party details','- GSTIN is present and valid for registered buyers.','- Place of supply matches the delivery state.','- Billing and shipping addresses are correct.','## Item details','- HSN code and GST rate are set on every item.','- Units of measure match what you actually deliver.','- Discounts are shown the way your accountant prefers.','## Totals','- Taxable value, tax and rounding add up.','- Freight and packing are taxed consistently.','## Before month-end','Run the invoice register for the month and look for blanks in GSTIN, HSN and place of supply. Fixing ten entries now is easier than fixing a return later.','> The best compliance habit is catching the error at the moment of entry, when the information is still fresh.'],'Anil Kapoor','Tally Consultant',false,389),
  ('route-planning-basics','Route planning basics for small sales teams','Field Sales','🗺️','2026-09-10',5,'A better route does not mean more visits. It means the right visits in the right order.',ARRAY['Most small teams plan routes by habit. A little deliberate planning can add several productive visits per week without extra travel.','## Group by area, not by name','Cluster retailers by locality and give each area a fixed weekday. Retailers learn when to expect you and keep their orders ready.','## Weight visits by value','- Top retailers: weekly.','- Mid-tier: every fortnight.','- Small shops: monthly, or by phone.','## Order within the day','Start at the farthest point and work back toward the office, so the last visits are close if something goes wrong. Keep a buffer for payment collection at the biggest accounts.','## Review the route monthly','Look at which visits produced no order, and ask why. Sometimes the retailer should move to a different day; sometimes he should be dropped from the route.'],'Priya Nair','Customer Success',false,426),
  ('stock-visibility-at-counter','Showing live stock at the order counter','Distribution','📦','2026-08-28',4,'Nothing frustrates a retailer more than an order that cannot be supplied. Live stock fixes it.',ARRAY['Booking an item that is not in the godown creates three problems: a short supply, an unhappy retailer and extra work to adjust the order.','## Show stock where the decision is made','When the salesman searches for an item, the available quantity should be right there beside it, refreshed from Tally by the connector.','## Handle shortages gracefully','- Warn, but allow booking when new stock is expected.','- Suggest an alternative pack size.','- Mark the line as backordered so billing knows.','## Keep stock accurate','Live stock is only as good as Tally. Post purchases and stock journals on the same day and the numbers on the phone will be trustworthy.'],'Rahul Menon','Product Manager',false,63),
  ('tally-mobile-faq','Tally on mobile: your questions answered','Tally Mobile','📲','2026-07-08',6,'Can I see outstanding on my phone? Does it work offline? Short answers to common questions.',ARRAY['## Can I see Tally data on my phone?','Yes, the parts that matter on the move: ledger balances, outstanding bills, stock positions and sales summaries. Your full books stay on the office PC.','## Does it work offline?','Salesmen can browse retailers, items and rates, and take orders without a signal. Orders are stored on the phone and sent as soon as the network returns.','## What happens if two people edit the same order?','The most recent saved version wins, and the earlier one is kept in the history, so nothing disappears.','## Is it secure?','- Every user has their own login.','- Roles control who can see rates, outstanding and reports.','- Lost phone? Disable the user and the access ends immediately.','## Do I need Tally Prime?','The connector works with Tally ERP 9 and Tally Prime. If you are on an older release, update it before installing.'],'Rahul Menon','Product Manager',false,100),
  ('onboarding-retailers-fast','Onboarding 300 retailers in a weekend','How-To','🚀','2026-04-16',5,'A practical guide to loading, cleaning and activating your retailer list without disrupting the week.',ARRAY['Importing retailers is the least glamorous step of any rollout and the one that decides whether everything else works.','## Step 1: Export from Tally','Pull your sundry debtors with address, GSTIN, phone and credit period. Open the file and look for duplicates and blanks before doing anything else.','## Step 2: Clean the list','- Merge the same shop entered under two names.','- Fill in the missing phone numbers; they power reminders.','- Mark closed shops as inactive.','## Step 3: Assign areas and salesmen','Give every retailer an area and an owner. This one step drives routes, targets and collection follow-up.','## Step 4: Send a welcome message','A short WhatsApp note introducing the new ordering process prevents confusion at the first visit.','> An hour spent cleaning the list on Saturday saves a week of correcting orders afterwards.'],'Priya Nair','Customer Success',false,137),
  ('monthly-close-checklist','A calmer month-end: the close checklist','How-To','✅','2026-03-26',5,'Month-end does not have to be a scramble. A simple order of operations makes it routine.',ARRAY['## Three days before','- Clear all pending orders: bill them or cancel them.','- Allocate receipts against bills.','- Post purchase invoices that are still on the desk.','## Last day','Take a stock count of the fast-moving lines and post adjustments. Print the ageing report and mark balances for follow-up.','## First day of the new month','- Verify GST registers for blanks.','- Compare the order book total with billed sales.','- Back up Tally data before anyone starts the next month''s entries.','## Review','Spend fifteen minutes with the team asking what slowed you down. Fix one thing each month and in a year the close will take half the time.'],'Anil Kapoor','Tally Consultant',false,174),
  ('whatsapp-orders-vs-app','WhatsApp orders versus an order app: an honest comparison','Comparisons','⚖️','2026-05-08',6,'WhatsApp is convenient for retailers, but it breaks down at scale. Here is where each one fits.',ARRAY['Many distributors already take orders on WhatsApp. It is familiar and quick, so the question is fair: why change?','## Where WhatsApp works well','For ten or fifteen regular customers, a message with the list is perfectly fine and needs no training.','## Where it starts to hurt','- Orders are free text, so someone must re-type them.','- There is no check against stock or rate.','- Messages get buried, and repeat orders are hard to find.','## The middle path','Keep WhatsApp for conversations, reminders and quick questions, and let an order app handle the order itself. Retailers still get their confirmation on WhatsApp; your team gets structured data.','> Use each tool for what it is good at. Chat for talking, forms for orders.'],'Rahul Menon','Product Manager',false,211),
  ('reading-outstanding-report','How to read an outstanding report without getting lost','Reports','🔍','2026-02-19',4,'Bill-wise or party-wise? Overdue or due? A short guide to the views that matter.',ARRAY['## Start party-wise','The party-wise view tells you who owes what. Sort by amount and look at the top twenty; they usually make up most of the total.','## Then drill bill-wise','For each large party, open the bills. You are looking for two things: very old bills, and bills that should already have been allocated against a receipt.','## Overdue versus due','- Overdue: the credit period has passed. This is where you act.','- Due: payment is expected soon. This is where you remind.','## Make it a conversation','Print the party-wise list for each salesman and ask for a payment date against every name. A column of dates is worth more than a column of totals.'],'Anil Kapoor','Tally Consultant',false,248),
  ('vendor-payables-discipline','Payables discipline: pay on time without draining cash','Payables','💳','2026-04-02',5,'Good supplier relationships are built on predictable payments. Plan them like you plan receipts.',ARRAY['Cash flow has two sides. Most distributors watch receivables closely and handle payables by memory.','## Know your due dates','List supplier bills by due date each week. A missed date costs goodwill, and often a discount.','## Pay in a rhythm','- Fix two payment days a week.','- Pay the strict suppliers first.','- Negotiate longer terms with those who allow it.','## Take early-payment discounts selectively','A two percent discount for paying ten days early is a strong return. Take it when cash is comfortable, skip it when it is not.','## Match payables to receipts','Look at expected collections for the week before approving payments. The goal is no surprises, not a bigger balance.'],'Anil Kapoor','Tally Consultant',false,285),
  ('tdl-customisations-guide','When to use TDL customisations (and when not to)','Integration','🧩','2026-03-05',5,'Custom TDL can fit Tally to your workflow. It can also create upgrade headaches. Choose carefully.',ARRAY['TDL lets you change how Tally behaves: new fields, new reports, different print formats. It is powerful, which is exactly why it needs restraint.','## Good reasons to customise','- A report your business needs every day that standard Tally lacks.','- A print format that customers or auditors insist on.','- A field you use for reconciliation, such as a route code.','## Reasons to hold back','Customising to match an old habit, rather than a real need, adds maintenance cost without adding value.','## Keep it maintainable','- Keep each customisation in a separate, named file.','- Document what it changes and why.','- Test on a copy of your data after every Tally upgrade.','> Customise the exceptions, not the rule.'],'Anil Kapoor','Tally Consultant',false,322),
  ('target-vs-achievement','Setting salesman targets that people believe in','Field Sales','🎯','2026-01-22',5,'Targets motivate when they are fair and visible, and demotivate when they feel arbitrary.',ARRAY['## Base them on history','Use last year''s same-month sales for each salesman, adjust for known changes in route or range, and add a modest stretch.','## Break them down','A monthly target is abstract. Convert it into a weekly figure and a few focus items, so the salesman knows what to do this week.','## Show progress daily','- Achievement against target on the home screen.','- Top-selling items for the week.','- Retailers not yet visited this month.','## Reward the behaviour you want','If you want collections as well as sales, include recovery in the incentive. People follow the scoreboard.'],'Priya Nair','Customer Success',false,359),
  ('retailer-loyalty-simple','Simple loyalty ideas for neighbourhood retailers','Schemes','⭐','2026-02-05',4,'You do not need a points app to say thank you. Three low-cost ideas that retailers remember.',ARRAY['## Quarterly recognition','A short list of top-purchasing retailers each quarter, with a small gift or a handwritten note, goes a long way.','## Early-payment bonus','A small credit note for retailers who pay within terms rewards the behaviour you want most.','## Product knowledge, not just discounts','- Bring samples of new products.','- Share quick tips on display.','- Offer a short training for the shop staff.','> Loyalty is the sum of small, consistent kindnesses, backed by reliable supply.'],'Meera Iyer','Content Lead',false,396),
  ('data-safety-for-small-business','Keeping your Tally data safe: a simple routine','Compliance','🔐','2026-01-08',4,'Backups, access and updates: three habits that protect your books.',ARRAY['## Back up daily, and test the backup','A backup you have never restored is a hope. Once a quarter, restore a copy on another PC and open it.','## Keep copies in two places','- One on the office PC or a drive.','- One off-site, such as an encrypted cloud folder.','## Control access','Give each person their own Tally user with only the rights they need. Remove users the day they leave.','## Update with care','Install Tally and Windows updates at month start, after a backup, and not in the middle of a close.'],'Anil Kapoor','Tally Consultant',false,433),
  ('first-100-orders','Your first 100 orders: a measurement guide','How-To','📈','2026-09-28',5,'How to tell, with real numbers, whether the new process is working for your team.',ARRAY['After a rollout, opinions are loud and data is quiet. Measure a few simple things in the first hundred orders.','## Time to book','How long does an order take from the retailer''s request to the office queue? It should fall in the first week.','## Corrections','Count the orders that needed a correction after booking. A healthy process trends toward fewer than one in twenty.','## Evening effort','Ask the operator how long the evening review takes. A drop from hours to minutes is the clearest sign of success.','## What to do with the numbers','- Share them at the weekly meeting.','- Celebrate the improvements.','- Pick one metric that is lagging and fix it in the next fortnight.'],'Rahul Menon','Product Manager',false,70);

COMMIT;

-- ---------- Detailed feature page content ----------
UPDATE cmr_admin.site_feature SET problem='Salesmen call the office with orders, scribble on chits, or forward WhatsApp messages. Rates, stock and a retailer''s pending dues are never in front of them at the counter.', solution='Give every salesman a phone app that shows live stock, the right rate, running schemes and the retailer''s outstanding balance – then lets them place the order in under a minute.',
  benefits=ARRAY['Live stock and rates|Items, rates and stock come straight from Tally, so nobody quotes a price or sells stock that is not there.','Dues before you sell|The retailer''s ledger balance and credit limit appear on the order screen, so overdue shops are handled before more goods leave.','Works in weak networks|Capture orders offline in lanes with no signal. They sync automatically when the phone is back online, without duplicates.','Schemes applied for you|Buy-10-get-1 and slab discounts apply as the quantity is entered. No mental maths, no disputes later.']::text[],
  stats=ARRAY['< 1 min|to place a typical order','0|orders re-typed in the office','Offline|capture, sync later']::text[],
  faqs=ARRAY['Does it work on any Android phone?|Yes. The app runs on ordinary Android phones; no special device is needed. Salesmen sign in with their own login and see only the routes you allow.','What happens if there is no network?|The order is saved on the phone and sent as soon as the connection returns. Each order carries a unique reference so it can never be posted twice.','Can a salesman change rates?|Only if you allow it. By default rates are read-only and come from your Tally price list.']::text[]
 WHERE slug='salesman-app';
UPDATE cmr_admin.site_feature SET problem='Orders arrive from many salesmen and several channels. Finding what is pending, what is approved and what is already billed means scrolling through chats and registers.', solution='One order list for the whole business. Filter by salesman, route, status or date, then turn any order into a GST invoice with a single tap.',
  benefits=ARRAY['Everything in one list|Salesman orders, retailer self-orders and office entries all land in the same place, newest first.','Filter and sort fast|Search by retailer or order number, filter by status, route or salesman and sort by value or date.','Order to invoice in one tap|Convert a confirmed order into an invoice without re-entering a single line.','Clear status trail|See who created, edited and approved each order and when.']::text[],
  stats=ARRAY['1 list|for all channels','1 tap|order to invoice','100%|traceable by user']::text[],
  faqs=ARRAY['Can I edit an order after it is placed?|Yes, until it is converted to an invoice. Edits are recorded in the order history.','Can I export orders?|Yes. The list can be exported to CSV with the filters you have applied.']::text[]
 WHERE slug='sales-orders';
UPDATE cmr_admin.site_feature SET problem='Orders placed by retailers themselves can be wrong – a wrong quantity, an item out of stock, a customer already over the credit limit – and by then stock has moved.', solution='Self-orders wait in an approval queue. You review, edit or reject them, and only approved orders move stock or become invoices.',
  benefits=ARRAY['You stay in control|Nothing reaches billing until a manager approves it.','Edit before approving|Adjust quantities or remove out-of-stock items while keeping the retailer informed.','Credit checks upfront|The retailer''s outstanding and limit are shown beside every pending order.','Clear reasons|Reject with a note so the retailer knows exactly why.']::text[],
  stats=ARRAY['100%|orders reviewed','0|surprise stock moves','1 queue|for every approval']::text[],
  faqs=ARRAY['Who can approve orders?|Owners and managers. Salesmen cannot approve their own or others'' orders.','Does the retailer get a notification?|Yes. They can be told on WhatsApp once the order is approved or changed.']::text[]
 WHERE slug='voucher-approval';
UPDATE cmr_admin.site_feature SET problem='Retailers phone in orders at odd hours, forget items, and expect someone to note everything down. Each phone call is time your team cannot spend selling.', solution='Share a personal order link with each retailer. They open it on their phone, pick items and send – no app to install and no password to remember.',
  benefits=ARRAY['No app install|The link opens in the phone browser. Retailers order the way they already use WhatsApp.','Personal to each shop|The page greets the retailer by name and uses their own rates and schemes.','Approval built in|Orders placed through the link wait for your approval before anything moves.','Share on WhatsApp|Send the link from the customer screen in one tap.']::text[],
  stats=ARRAY['0|apps to install','24x7|ordering for retailers','1 link|per retailer']::text[],
  faqs=ARRAY['Is the link safe?|Each link is unique to a retailer. In production it should carry a signed, expiring token so it cannot be guessed.','Can retailers see other customers'' data?|No. The page shows only their own name, rates and the items you have made available.']::text[]
 WHERE slug='customer-order-link';
UPDATE cmr_admin.site_feature SET problem='Generating an IRN means exporting data, logging into a portal and copying details back by hand. It slows billing and invites typing errors.', solution='Produce the e-invoice details from the invoice screen and keep the IRN and acknowledgement with the invoice, ready to print or send.',
  benefits=ARRAY['From the invoice screen|No separate portal visit; the details are captured where you already work.','Stored with the invoice|IRN and acknowledgement number are saved on the invoice and print on the document.','Fewer rejections|GSTIN, tax split and totals are validated before you submit.','Audit friendly|See who generated which IRN and when.']::text[],
  stats=ARRAY['1 screen|to bill and e-invoice','0|copy-paste steps','Audit|trail on every IRN']::text[],
  faqs=ARRAY['Is IRN generation live?|In this demo it is simulated so you can see the flow. The production product connects to your GST e-invoice provider.','Which invoices need an e-invoice?|Those that fall under the turnover threshold set by GST rules. SyncTally can be set to prompt only for those customers.']::text[]
 WHERE slug='e-invoice';
UPDATE cmr_admin.site_feature SET problem='Goods are ready to leave but the transporter details, distance and e-way bill still have to be entered on another system.', solution='Capture vehicle number and distance on the invoice, generate the e-way bill and keep the number with the invoice and challan.',
  benefits=ARRAY['Vehicle and distance on the invoice|Enter transport details at dispatch time, from the phone.','Number stored and printed|The e-way bill number appears on the invoice and challan copy.','Right place, right time|Raise the bill the moment the truck is loaded, not hours later at the desk.','One record|Invoice, challan and e-way bill are linked together.']::text[],
  stats=ARRAY['1 form|for vehicle and distance','0|separate portal logins','Linked|invoice + challan + EWB']::text[],
  faqs=ARRAY['Is this simulated in the demo?|Yes, e-way bill numbers are mocked here. The paid product links to your e-way bill provider.','Can I update the vehicle later?|Yes. Update the vehicle details and the change is recorded against the same bill.']::text[]
 WHERE slug='e-way-bill';
UPDATE cmr_admin.site_feature SET problem='Sales returns and rate differences are handled on paper. The retailer''s balance and ageing go out of date until someone posts the entry in Tally.', solution='Record a credit or debit note against an invoice. The retailer''s balance, ageing and ledger update straight away.',
  benefits=ARRAY['Linked to the invoice|Pick the original invoice so the note and the bill stay together.','Balances update instantly|Outstanding and ageing reflect the note the moment it is saved.','Goes back to Tally|Notes sync as vouchers, so books and app always agree.','Printable|Share a clean credit note with the retailer on WhatsApp.']::text[],
  stats=ARRAY['Instant|balance update','0|paper chits','Synced|to Tally']::text[],
  faqs=ARRAY['Can I issue a partial credit note?|Yes. Select the lines and quantities being returned or the rate difference being passed on.','Does it affect stock?|Sales returns can add stock back to the selected godown; rate-difference notes do not.']::text[]
 WHERE slug='credit-debit-notes';
UPDATE cmr_admin.site_feature SET problem='Supplier invoices arrive as PDFs and someone retypes every line into Tally, hoping not to mis-key a rate or tax.', solution='Upload the supplier''s PDF and get a draft purchase voucher with items, quantities, rates and tax filled in for you to review.',
  benefits=ARRAY['Draft in seconds|Lines are read from the PDF and placed in a draft you can check.','You stay in charge|Nothing posts until you review and confirm.','Items matched|Supplier items are matched to your own stock items to avoid duplicates.','Straight to Tally|Confirmed purchases sync as vouchers.']::text[],
  stats=ARRAY['Seconds|not minutes per bill','1|review step before posting','Fewer|typing errors']::text[],
  faqs=ARRAY['Does it read every PDF format?|It works best on text-based PDFs. Scanned images may need a clearer copy; you can always correct the draft by hand.','Is the demo import real?|The demo shows the flow with sample data; production uses document-reading on your uploaded files.']::text[]
 WHERE slug='import-purchase-pdf';
UPDATE cmr_admin.site_feature SET problem='Retailers still send handwritten slips as photos on WhatsApp. Someone has to read the slip and key in every line.', solution='Photograph the slip, and SyncTally drafts the order lines for you to confirm.',
  benefits=ARRAY['Snap and draft|Take or upload a photo of the order slip.','Matches your item names|Handwritten names are matched to your item list.','Confirm, don''t retype|Fix the few lines that need correction and place the order.','Saves evening data entry|Turns the daily slip pile into orders in minutes.']::text[],
  stats=ARRAY['1 photo|one draft order','Minutes|not hours of typing','You|confirm every order']::text[],
  faqs=ARRAY['Will it understand messy handwriting?|It does its best and always shows the draft for your confirmation, so a misread line is caught before the order is placed.','Is this live in the demo?|It is simulated in the demo.']::text[]
 WHERE slug='order-from-photo';
UPDATE cmr_admin.site_feature SET problem='Payments arrive in the bank but the retailer''s invoice stays open until someone matches each credit by hand.', solution='Upload your bank statement and SyncTally proposes which credit belongs to which retailer and invoice. You confirm, receipts post.',
  benefits=ARRAY['Smart matching|Narration, amount and name hints are used to suggest the retailer.','Review before posting|You approve every match; unmatched credits stay for manual action.','Oldest invoices first|Receipts settle the oldest open invoices of the retailer.','Month-end easier|Reconciliation stops being a last-week-of-the-month panic.']::text[],
  stats=ARRAY['1 CSV|to reconcile a day','Oldest-first|settlement','0|guesswork on unmatched']::text[],
  faqs=ARRAY['Which bank formats work?|Any statement exported as CSV with date, description and amount columns. A sample file is provided.','Can I undo a match?|Yes, until the receipt is synced. After that, post a reversing entry.']::text[]
 WHERE slug='bank-statement-import';
UPDATE cmr_admin.site_feature SET problem='Stock sits in more than one godown, and the billing desk can''t tell which godown has what – so trucks are loaded from the wrong place.', solution='Track stock godown by godown, choose the source at billing time and print loading sheets sorted by route.',
  benefits=ARRAY['Godown-wise visibility|See exactly what each godown holds, live.','Pick source when billing|Allocate each invoice line to a godown.','Loading sheets by route|Print a sheet per truck so loading follows the delivery sequence.','Fewer mix-ups|Staff load what the sheet says, not what they remember.']::text[],
  stats=ARRAY['Per godown|stock view','1 sheet|per truck','Route|wise loading']::text[],
  faqs=ARRAY['Does it sync with Tally godowns?|Yes. Godowns in Tally appear here and movements sync back.','Can I transfer stock between godowns?|Stock transfers can be recorded and are posted to Tally as stock journals.']::text[]
 WHERE slug='godown-stock';
UPDATE cmr_admin.site_feature SET problem='The driver needs a document for the shop, but the invoice shows prices the retailer''s staff should not see.', solution='Print a price-free delivery challan from any invoice, with a signature box for the receiver.',
  benefits=ARRAY['Price-free copy|Quantities and items only; no rates or totals.','One click from the invoice|No re-typing; the challan is built from the invoice.','Receiver signature|A signature area for proof of delivery.','Linked records|Challan, invoice and e-way bill stay connected.']::text[],
  stats=ARRAY['1 click|invoice to challan','0|prices shown to drivers','Signed|proof of delivery']::text[],
  faqs=ARRAY['Can the challan show batch or expiry?|Yes, for items where batch or expiry is tracked.','Can I reprint a challan?|Yes. It can be reprinted any time from the invoice.']::text[]
 WHERE slug='delivery-challans';
UPDATE cmr_admin.site_feature SET problem='Every invoice looks the same and carries no payment instructions, so retailers ask how to pay.', solution='Choose a template, add your footer note and UPI ID, and every invoice goes out looking professional with a way to pay.',
  benefits=ARRAY['Pick a look|Classic, compact and modern templates.','Your note and UPI ID|Add a footer message and UPI ID shown on every invoice.','Company-aware|The active company''s name and details print automatically.','Print or WhatsApp|The same polished invoice for print and chat.']::text[],
  stats=ARRAY['3|ready templates','UPI|ID on every bill','1 setting|for all invoices']::text[],
  faqs=ARRAY['Can I add my logo?|Logo support is part of the paid product; the demo lets you choose templates and footer text.','Will old invoices change?|Templates change how a document prints; the invoice data stays the same.']::text[]
 WHERE slug='invoice-template';
UPDATE cmr_admin.site_feature SET problem='Retailers keep asking for their statement. Preparing and sending one takes a call, an export and an attachment.', solution='Send a retailer their statement – invoices, receipts and balance – as a WhatsApp message with a few taps.',
  benefits=ARRAY['Always current|The statement is built from live ledger data.','Message you can edit|Review and tweak the text before it opens in WhatsApp.','Pay link included|Add a UPI payment link to the same message.','Logged|Every send is recorded against the retailer.']::text[],
  stats=ARRAY['3 taps|statement to retailer','Live|ledger data','Logged|every message']::text[],
  faqs=ARRAY['Does it send automatically?|The app opens WhatsApp with the message ready and you press send. Automatic sending needs the WhatsApp Business API in the paid product.','Which number is used?|Your own WhatsApp, or the shared SyncTally number, depending on your plan.']::text[]
 WHERE slug='ledger-on-whatsapp';
UPDATE cmr_admin.site_feature SET problem='Calling every overdue retailer is awkward and often forgotten. Dues age quietly while the team is busy selling.', solution='Send a friendly WhatsApp reminder with the amount, the oldest invoice and a UPI link, directly from the retailer''s screen.',
  benefits=ARRAY['Polite and specific|Names the amount and the oldest unpaid invoice.','Template-based|Edit the message once and reuse it.','Pay in one tap|Includes a UPI payment link.','Remembered|You can see when a retailer was last reminded.']::text[],
  stats=ARRAY['1 tap|reminder','UPI|link included','History|of every nudge']::text[],
  faqs=ARRAY['Can I change the wording?|Yes. Templates support placeholders such as customer name, amount and days overdue.','Will retailers be spammed?|Reminders are sent only when you send them, or when your automatic rules say so with a minimum gap.']::text[]
 WHERE slug='payment-reminders';
UPDATE cmr_admin.site_feature SET problem='Reminders depend on someone remembering to send them, so they stop when the office gets busy.', solution='Set rules once – minimum amount, days overdue, repeat gap – and SyncTally queues the reminders for you every day.',
  benefits=ARRAY['Rules, not memory|Define who should be reminded and how often.','Daily queue|Each day''s reminders are ready to send.','Skip the small stuff|A minimum amount avoids nagging for tiny balances.','Escalation|Repeat gaps keep follow-ups steady and polite.']::text[],
  stats=ARRAY['Daily|queue built for you','1 time|setup','Rules|you control']::text[],
  faqs=ARRAY['Are messages sent without my approval?|In the demo the queue is prepared and you open WhatsApp to send. Fully automatic sending is part of the production setup.','Can I exclude a retailer?|Yes. Turn off reminders for a specific customer.']::text[]
 WHERE slug='automatic-reminders';
UPDATE cmr_admin.site_feature SET problem='Dues live in Tally reports that nobody checks on the road. Collection starts late and credit limits are crossed without anyone noticing.', solution='See who owes what – by retailer, route or salesman – with credit-limit warnings, on your phone.',
  benefits=ARRAY['Outstanding by retailer|A ranked list with total due and overdue amounts.','Credit-limit alerts|Highlights retailers over their limit.','Drill into invoices|Tap a retailer to see each open invoice and its age.','Act from the list|Remind, call or record a receipt right there.']::text[],
  stats=ARRAY['Live|from your ledgers','Ranked|biggest dues first','1 tap|to remind or collect']::text[],
  faqs=ARRAY['Does it match Tally?|It is built from the same invoices and receipts that sync with Tally.','Can salesmen see it?|Salesmen see only their own routes'' retailers, according to the roles you set.']::text[]
 WHERE slug='outstanding-receivables';
UPDATE cmr_admin.site_feature SET problem='A single outstanding number hides the real risk: how much is 90 days old.', solution='See each retailer''s balance split into 0–30, 31–60, 61–90 and 90+ day buckets.',
  benefits=ARRAY['Four ageing buckets|Understand risk at a glance.','Retailer and route views|Slice by retailer, route or salesman.','Focus on the oldest|Sort by 90+ to start where it matters.','Export|Download for meetings with your accountant.']::text[],
  stats=ARRAY['4|ageing buckets','90+|highlighted','CSV|export']::text[],
  faqs=ARRAY['How is age calculated?|From the invoice date, settled oldest-first by receipts.','Can I change the buckets?|The standard buckets are 0–30, 31–60, 61–90 and 90+ days.']::text[]
 WHERE slug='debtor-ageing';
UPDATE cmr_admin.site_feature SET problem='Cash collected in the field is written on chits and posted days later, so balances are wrong when the next order is taken.', solution='Record cash, UPI, cheque and bank receipts on the spot. They settle the oldest invoices first and update the balance immediately.',
  benefits=ARRAY['Receipts in the field|Record the payment where it is received.','Oldest-first settlement|Keeps ageing accurate.','All modes|Cash, UPI, cheque and bank transfer.','Synced to Tally|Receipt vouchers post automatically.']::text[],
  stats=ARRAY['Instant|balance update','4|payment modes','Synced|to Tally']::text[],
  faqs=ARRAY['Can I record a cheque that is not cleared?|Yes. Note the cheque details and mark it as received; clear it when it is banked.','Is there a receipt for the retailer?|A receipt message can be shared on WhatsApp.']::text[]
 WHERE slug='payment-collection';
UPDATE cmr_admin.site_feature SET problem='Collection teams call in random order, with no script and no record of what was promised.', solution='Get a prioritised call queue with a suggested script, and log promises-to-pay so follow-ups don''t slip.',
  benefits=ARRAY['Smart queue|Retailers ordered by amount and days overdue.','Suggested script|A polite, specific opening for each call.','Promise tracking|Log the date a retailer promised to pay.','Follow-up reminders|See broken promises first.']::text[],
  stats=ARRAY['Ranked|call list','Script|for each call','Promise|dates tracked']::text[],
  faqs=ARRAY['Does the app place the calls?|In this demo it prepares the queue and script; calls are made by your team.','Is voice calling available?|Automated voice calling is a roadmap item, not part of the demo.']::text[]
 WHERE slug='ai-collection-calls';
UPDATE cmr_admin.site_feature SET problem='Tally runs on one office PC. Everyone else waits for printouts or phone calls to know a balance or stock level.', solution='The Tally Connector links SyncTally to your Tally. Masters come in, vouchers go back – so the whole team works from a phone.',
  benefits=ARRAY['Masters pulled in|Items, ledgers and prices appear in the app.','Vouchers pushed back|Invoices, receipts and notes post to Tally.','Read-only safety|Rates and master data are protected by roles.','Tally Prime and ERP 9|Works with both.']::text[],
  stats=ARRAY['2-way|sync','0|double entry','2|Tally versions']::text[],
  faqs=ARRAY['Do I need to change how I use Tally?|No. Keep working in Tally; SyncTally reads and writes through the connector.','What if the PC is off?|The app keeps working and syncs when the connector is online again.']::text[]
 WHERE slug='tally-on-mobile';
UPDATE cmr_admin.site_feature SET problem='Remote desktop tools are slow, risky and tie up the one PC where Tally lives.', solution='The connector talks to Tally on your own PC and sends only what the app needs. No remote desktop, no open ports.',
  benefits=ARRAY['Outbound only|The connector only makes outgoing connections.','Less exposure|No inbound ports opened on your network.','Just the data needed|Only order and outstanding data is synced.','Fast|No laggy screen sharing.']::text[],
  stats=ARRAY['0|open ports','0|remote desktop sessions','Outbound|only']::text[],
  faqs=ARRAY['Is my full Tally data uploaded?|No. Only the items, ledger balances and vouchers the app needs are synced.','Do I need a static IP?|No.']::text[]
 WHERE slug='without-remote-access';
